insert into public.events (slug, start_year, end_year, is_approximate, importance, wikidata_id, status, published_at) values ('writing-begins-in-sumer', -3200, null, true, 1, null, 'published', now())
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'writing-begins-in-sumer'), 'en', 'Writing begins in Sumer', 'Scribes in cities like Uruk press wedge-shaped marks into clay tablets to keep records of grain and goods. Cuneiform is one of the first writing systems, and it marks the start of recorded history.', 'Mesopotamia (Iraq)', 'Clay tablet with cuneiform signs', array['cuneiform', 'sumerian', 'iraq', 'ancient'])
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'writing-begins-in-sumer'), 'ar', 'بداية الكتابة في سومر', 'يضغط الكتبة في مدن مثل أوروك علامات على شكل أسافين في ألواح من الطين لتسجيل الحبوب والبضائع. الكتابة المسمارية من أولى أنظمة الكتابة، وبها يبدأ التاريخ المدوَّن.', 'بلاد الرافدين (العراق)', 'لوح طيني عليه كتابة مسمارية', array['الكتابة', 'المسمارية', 'سومر', 'السومريون', 'أوروك', 'العراق'])
