insert into public.events (slug, start_year, end_year, is_approximate, importance, wikidata_id, status, published_at) values ('upper-and-lower-egypt-unite', -3100, null, true, 2, null, 'published', now())
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'upper-and-lower-egypt-unite'), 'en', 'Upper and Lower Egypt unite', 'Tradition credits King Narmer (Menes) with joining Upper and Lower Egypt into one kingdom, the start of the age of the pharaohs.', 'Egypt', 'The Narmer Palette', '{}'::text[])
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'upper-and-lower-egypt-unite'), 'ar', 'توحيد مصر العليا والسفلى', 'تنسب الروايات إلى الملك نارمر (مينا) توحيد مصر العليا والسفلى في مملكة واحدة، وبذلك يبدأ عصر الفراعنة.', 'مصر', 'لوحة نارمر', array['نارمر', 'مينا', 'توحيد', 'مصر', 'الفراعنة'])
