insert into public.events (slug, start_year, end_year, is_approximate, importance, wikidata_id, status, published_at) values ('great-pyramid-of-giza', -2560, null, true, 1, 'Q37200', 'published', now())
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'great-pyramid-of-giza'), 'en', 'Great Pyramid of Giza', 'Built as a tomb for the pharaoh Khufu, it remained the tallest human-made structure on Earth for roughly 3,800 years.', 'Giza, Egypt', 'The Great Pyramid on the Giza plateau', array['pyramids', 'giza', 'khufu', 'pharaoh', 'egyptian', 'ancient'])
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'great-pyramid-of-giza'), 'ar', 'الهرم الأكبر في الجيزة', 'بُني مقبرةً للفرعون خوفو، وظل أعلى بناء صنعه الإنسان على الأرض نحو 3,800 سنة.', 'الجيزة، مصر', 'الهرم الأكبر على هضبة الجيزة', array['الهرم', 'الأهرامات', 'الجيزة', 'خوفو', 'فرعون'])
insert into public.events (slug, start_year, end_year, is_approximate, importance, wikidata_id, status, published_at) values ('code-of-hammurabi', -1754, null, true, 2, null, 'published', now())
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'code-of-hammurabi'), 'en', 'Code of Hammurabi', 'King Hammurabi of Babylon has 282 laws carved on a basalt stele. It is one of the oldest written law codes known.', 'Babylon (Iraq)', 'The stele of Hammurabi', array['law', 'babylonian', 'iraq'])
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'code-of-hammurabi'), 'ar', 'شريعة حمورابي', 'ينقش حمورابي ملك بابل 282 قانونًا على مسلة من البازلت، وهي من أقدم مجموعات القوانين المكتوبة المعروفة.', 'بابل (العراق)', 'مسلة حمورابي', array['حمورابي', 'قانون', 'قوانين', 'بابل', 'العراق'])
insert into public.events (slug, start_year, end_year, is_approximate, importance, wikidata_id, status, published_at) values ('tutankhamun-becomes-pharaoh', -1332, null, true, 3, null, 'published', now())
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'tutankhamun-becomes-pharaoh'), 'en', 'Tutankhamun becomes pharaoh', 'The boy king, about eight or nine years old, rules for about nine years. His tomb, found nearly intact in 1922, makes him one of the best-known pharaohs.', 'Egypt', 'Tutankhamun’s golden mask', '{}'::text[])
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'tutankhamun-becomes-pharaoh'), 'ar', 'توت عنخ آمون يصبح فرعونًا', 'يتولى الملك الصبي الحكم في نحو الثامنة أو التاسعة من عمره ويحكم نحو تسع سنوات. مقبرته التي عُثر عليها شبه سليمة عام 1922 جعلته من أشهر الفراعنة.', 'مصر', 'القناع الذهبي لتوت عنخ آمون', array['توت', 'عنخ', 'آمون', 'فرعون', 'مقبرة'])
