insert into public.events (slug, start_year, end_year, is_approximate, importance, wikidata_id, status, published_at) values ('first-recorded-olympic-games', -776, null, false, 2, null, 'published', now())
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'first-recorded-olympic-games'), 'en', 'First recorded Olympic Games', 'The earliest recorded Games are held at Olympia. Greeks later count years in four-year Olympiads starting from this date.', 'Olympia, Greece', 'Ruins of the stadium at Olympia', '{}'::text[])
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'first-recorded-olympic-games'), 'ar', 'أول ألعاب أولمبية مسجلة', 'تُقام أقدم ألعاب مسجلة في أولمبيا. وفيما بعد صار الإغريق يعدّون السنين بدورات أولمبية مدة كل منها أربع سنوات تبدأ من هذا التاريخ.', 'أولمبيا، اليونان', 'أطلال الملعب في أولمبيا', array['الألعاب', 'الأولمبية', 'أولمبيا', 'الإغريق', 'رياضة'])
insert into public.events (slug, start_year, end_year, is_approximate, importance, wikidata_id, status, published_at) values ('roman-republic-founded', -509, null, false, 3, null, 'published', now())
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'roman-republic-founded'), 'en', 'Roman Republic founded', 'Romans expel their last king and set up a republic run by elected officials and a Senate.', 'Rome', 'Ruins of the Roman Forum', '{}'::text[])
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'roman-republic-founded'), 'ar', 'قيام الجمهورية الرومانية', 'يطرد الرومان آخر ملوكهم ويقيمون جمهورية يديرها مسؤولون منتخبون ومجلس الشيوخ.', 'روما', 'أطلال الفوروم الروماني', array['الجمهورية', 'الرومانية', 'روما', 'مجلس', 'الشيوخ'])
insert into public.events (slug, start_year, end_year, is_approximate, importance, wikidata_id, status, published_at) values ('campaigns-of-alexander', -334, -323, false, 2, null, 'published', now())
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'campaigns-of-alexander'), 'en', 'Campaigns of Alexander', 'Alexander of Macedon defeats the Persian Empire and marches as far as the Indus River, spreading Greek culture across the Middle East.', 'Greece to India', 'The Alexander Mosaic, Pompeii', '{}'::text[])
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'campaigns-of-alexander'), 'ar', 'حملات الإسكندر', 'يهزم الإسكندر المقدوني الإمبراطورية الفارسية ويزحف حتى نهر السند، فينشر الثقافة الإغريقية في أنحاء الشرق الأوسط.', 'من اليونان إلى الهند', 'فسيفساء الإسكندر، بومبي', array['الإسكندر', 'المقدوني', 'الأكبر', 'الفرس', 'فارس'])
insert into public.events (slug, start_year, end_year, is_approximate, importance, wikidata_id, status, published_at) values ('qin-unifies-china', -221, null, false, 2, null, 'published', now())
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'qin-unifies-china'), 'en', 'Qin unifies China', 'Qin Shi Huang conquers the rival states and becomes China’s first emperor. He standardizes writing, coins and measures.', 'China', 'The Terracotta Army, Xi’an', array['china', 'chinese', 'emperor'])
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'qin-unifies-china'), 'ar', 'أسرة تشين توحّد الصين', 'يغزو تشين شي هوانغ الممالك المتنافسة ويصبح أول إمبراطور للصين، ويوحّد الكتابة والعملة والمقاييس.', 'الصين', 'جيش الطين، شيان', array['الصين', 'الصيني', 'إمبراطور', 'تشين'])
insert into public.events (slug, start_year, end_year, is_approximate, importance, wikidata_id, status, published_at) values ('julius-caesar-assassinated', -44, null, false, 2, null, 'published', now())
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'julius-caesar-assassinated'), 'en', 'Julius Caesar assassinated', 'Senators stab Caesar on the Ides of March. The civil wars that follow end the Republic and bring Augustus to power as the first emperor.', 'Rome', 'Site of the Theatre of Pompey, Rome', '{}'::text[])
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'julius-caesar-assassinated'), 'ar', 'اغتيال يوليوس قيصر', 'يطعن أعضاء مجلس الشيوخ قيصر في منتصف شهر مارس. والحروب الأهلية التي تلت ذلك أنهت الجمهورية وجاءت بأغسطس أول إمبراطور.', 'روما', 'موقع مسرح بومبي، روما', array['قيصر', 'يوليوس', 'اغتيال', 'روما', 'أغسطس'])
insert into public.events (slug, start_year, end_year, is_approximate, importance, wikidata_id, status, published_at) values ('death-of-cleopatra', -30, null, false, 3, null, 'published', now())
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'death-of-cleopatra'), 'en', 'Death of Cleopatra', 'Cleopatra VII, the last ruler of Ptolemaic Egypt, dies after her defeat by Octavian. Egypt becomes a Roman province.', 'Alexandria, Egypt', 'Bust of Cleopatra VII', '{}'::text[])
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'death-of-cleopatra'), 'ar', 'وفاة كليوباترا', 'تموت كليوباترا السابعة، آخر حكام مصر البطلمية، بعد هزيمتها أمام أوكتافيوس، فتصبح مصر ولاية رومانية.', 'الإسكندرية، مصر', 'تمثال نصفي لكليوباترا السابعة', array['كليوباترا', 'البطالمة', 'الإسكندرية', 'مصر'])
insert into public.events (slug, start_year, end_year, is_approximate, importance, wikidata_id, status, published_at) values ('fall-of-western-rome', 476, null, false, 1, null, 'published', now())
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'fall-of-western-rome'), 'en', 'Fall of Western Rome', 'The Germanic leader Odoacer removes Romulus Augustulus, the last western emperor. The eastern half continues as the Byzantine Empire for almost 1,000 more years.', 'Italy', 'Coin of Romulus Augustulus', '{}'::text[])
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'fall-of-western-rome'), 'ar', 'سقوط روما الغربية', 'يعزل الزعيم الجرماني أودواكر رومولوس أوغسطولوس، آخر أباطرة الغرب. ويستمر النصف الشرقي باسم الإمبراطورية البيزنطية قرابة ألف سنة أخرى.', 'إيطاليا', 'عملة رومولوس أوغسطولوس', array['سقوط', 'روما', 'الرومانية', 'بيزنطة'])
insert into public.events (slug, start_year, end_year, is_approximate, importance, wikidata_id, status, published_at) values ('the-hijra', 622, null, false, 1, null, 'published', now())
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'the-hijra'), 'en', 'The Hijra', 'The Prophet Muhammad migrates from Mecca to Medina. This year becomes year 1 of the Islamic (Hijri) calendar.', 'Mecca to Medina', 'Masjid an-Nabawi, Medina', array['islam', 'islamic', 'muhammad', 'prophet', 'hijri', 'calendar'])
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'the-hijra'), 'ar', 'الهجرة النبوية', 'يهاجر النبي محمد ﷺ من مكة إلى المدينة. وتصبح هذه السنة السنةَ الأولى في التقويم الإسلامي (الهجري).', 'من مكة إلى المدينة', 'المسجد النبوي، المدينة المنورة', array['الهجرة', 'النبي', 'محمد', 'الإسلام', 'الهجري', 'التقويم', 'مكة', 'المدينة'])
insert into public.events (slug, start_year, end_year, is_approximate, importance, wikidata_id, status, published_at) values ('baghdad-founded', 762, null, false, 2, null, 'published', now())
