insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = 'norman-conquest-of-england'), 'ar', 'الغزو النورماني لإنجلترا', 'ينتصر وليام النورماندي في معركة هاستينغز ويُتوَّج ملكًا على إنجلترا.', 'إنجلترا', 'جزء من نسيج بايو', array['النورمان', 'إنجلترا', 'هاستينغز', 'وليام'])
