insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = '1948-arab-israeli-war'), 'en', '1948 Arab–Israeli War', 'Israel declares independence on 14 May 1948 as the British Mandate ends, and neighboring Arab states go to war. About 700,000 Palestinians flee or are expelled from their homes, an event Palestinians call the Nakba (“catastrophe”).', 'Israel and Palestine', 'Map of the 1949 armistice lines', array['israel', 'israeli', 'palestine', 'palestinian', 'nakba', 'independence', 'arab', 'war', 'conflict'])
insert into public.event_translations (event_id, locale, title, summary, place_label, media_hint, keywords) values ((select id from public.events where slug = '1948-arab-israeli-war'), 'ar', 'حرب 1948 العربية الإسرائيلية', 'تعلن إسرائيل قيامها في 14 مايو 1948 مع انتهاء الانتداب البريطاني، وتدخل الدول العربية المجاورة الحرب. يفرّ نحو 700 ألف فلسطيني من بيوتهم أو يُطردون منها، وهو ما يسميه الفلسطينيون النكبة.', 'إسرائيل وفلسطين', 'خريطة خطوط الهدنة لعام 1949', array['النكبة', 'فلسطين', 'الفلسطينيون', 'إسرائيل', 'حرب', '1948', 'اللاجئون'])
